package kr.releasepilot.controlplane.analysis;
import kr.releasepilot.controlplane.release.ReleaseRepository;import kr.releasepilot.controlplane.rollout.*;import kr.releasepilot.controlplane.shared.error.NotFoundException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import tools.jackson.databind.*;import java.util.*;
@Service public class AnalysisQueryService{private final ReleaseRepository releases;private final RolloutExecutionRepository executions;private final RolloutStepRepository steps;private final AnalysisJobRepository jobs;private final ObjectMapper json;public AnalysisQueryService(ReleaseRepository releases,RolloutExecutionRepository executions,RolloutStepRepository steps,AnalysisJobRepository jobs,ObjectMapper json){this.releases=releases;this.executions=executions;this.steps=steps;this.jobs=jobs;this.json=json;}@Transactional(readOnly=true)public List<View> byRelease(UUID releaseId){if(!releases.existsById(releaseId))throw new NotFoundException("RELEASE_NOT_FOUND","Release not found");var execution=executions.findByReleaseId(releaseId);if(execution.isEmpty())return List.of();var rolloutSteps=steps.findByExecutionIdOrderByStepIndexAsc(execution.get().getId());var indexById=new HashMap<UUID,Integer>();for(var step:rolloutSteps)indexById.put(step.getId(),step.getStepIndex());return jobs.findByStepIdIn(indexById.keySet()).stream().map(j->new View(j.getId(),indexById.get(j.getStepId()),j.getStatus(),j.getAttempts(),j.getVerdict(),j.getReasonCode(),evidence(j.getEvidenceJson()))).sorted(Comparator.comparingInt(View::stepIndex)).toList();}private JsonNode evidence(String value){if(value==null)return json.createArrayNode();try{return json.readTree(value);}catch(Exception e){throw new IllegalStateException("Stored analysis evidence is invalid",e);}}}
record View(UUID id,int stepIndex,AnalysisJobStatus status,int attempts,AnalysisVerdict verdict,String reasonCode,JsonNode evidence){}
